/**
 * @jest-environment node
 */
// aifolders.xyz is pre-rendered: one home page and one privacy page per language,
// generated by tools/build-site.js from the builders in docs/site/app.js. These
// tests hold the SEO contract of those pages, and — first of all — that the
// committed HTML is what the generator produces today. Edit app.js or an i18n
// file without regenerating and the live site keeps the old text; this is what
// catches it. Fix: `node tools/build-site.js`, then commit docs/.
const fs = require('fs');
const path = require('path');
const { renderAll, stale, normalize } = require('../tools/build-site.js');

const ROOT = path.join(__dirname, '..');
const DOCS = path.join(ROOT, 'docs');
const ORIGIN = 'https://aifolders.xyz';
const pages = renderAll();
const htmlPages = Object.keys(pages).filter((p) => p.endsWith('.html'));

const attr = (html, re) => (html.match(re) || [])[1];

describe('committed pages', () => {
  test('match what tools/build-site.js generates', () => {
    expect(stale(pages)).toEqual([]);
  });

  test('cover 43 languages x 2 pages, plus the sitemap', () => {
    expect(htmlPages).toHaveLength(86);
    expect(pages['index.html']).toBeDefined();
    // The stores and the extensions link to these two; they must stay English.
    expect(pages['privacy.html']).toMatch(/<html lang="en"/);
    expect(pages['index.html']).toMatch(/<html lang="en"/);
  });
});

describe.each(htmlPages)('%s', (rel) => {
  const html = pages[rel];
  const selfUrl = ORIGIN + '/' + rel.replace(/(^|\/)index\.html$/, '$1');

  test('is canonical to itself', () => {
    expect(attr(html, /<link rel="canonical" href="([^"]+)">/)).toBe(selfUrl);
  });

  test('declares every language version, itself and an x-default', () => {
    const alts = [...html.matchAll(/<link rel="alternate" hreflang="([^"]+)" href="([^"]+)">/g)];
    expect(alts).toHaveLength(44);
    expect(alts.map((m) => m[2])).toContain(selfUrl);
    const xd = alts.find((m) => m[1] === 'x-default');
    expect(xd[2]).toBe(ORIGIN + (rel.endsWith('privacy.html') ? '/privacy.html' : '/'));
    // hreflang targets are pages this build actually writes.
    for (const [, , href] of alts) {
      const target = href.slice(ORIGIN.length + 1).replace(/(^|\/)$/, '$1index.html') || 'index.html';
      expect(pages[target]).toBeDefined();
    }
  });

  test('carries its text in the HTML, not only after JavaScript runs', () => {
    const main = html.slice(html.indexOf('<main id="app">'), html.indexOf('</main>'));
    expect(main).toMatch(/<h1[ >]/);
    expect(main.replace(/<[^>]+>/g, '').trim().length).toBeGreaterThan(500);
  });

  test('has a title and a description of search-snippet size', () => {
    expect(attr(html, /<title>([^<]+)<\/title>/)).toBeTruthy();
    const d = attr(html, /<meta name="description" content="([^"]+)">/);
    expect(d.length).toBeGreaterThan(25); // CJK says a lot in few characters
    expect(d.length).toBeLessThanOrEqual(180);
  });

  test('uses root-relative asset paths, so it works one directory down', () => {
    expect(html).not.toMatch(/(src|href)="site\//);
  });

  test('references only images that exist', () => {
    for (const [, src] of html.matchAll(/<img[^>]+src="(\/site\/[^"]+)"/g)) {
      expect(fs.existsSync(path.join(DOCS, src))).toBe(true);
    }
  });

  test('structured data parses', () => {
    const json = attr(html, /<script type="application\/ld\+json">\n([\s\S]*?)\n<\/script>/);
    expect(() => JSON.parse(json)).not.toThrow();
  });
});

test('home page titles are unique per language', () => {
  const titles = htmlPages.filter((p) => p.endsWith('index.html'))
    .map((p) => attr(pages[p], /<title>([^<]+)<\/title>/));
  expect(new Set(titles).size).toBe(titles.length);
});

test('the sitemap lists every page and nothing else', () => {
  const locs = [...pages['sitemap.xml'].matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]).sort();
  const expected = htmlPages.map((p) => ORIGIN + '/' + p.replace(/(^|\/)index\.html$/, '$1')).sort();
  expect(locs).toEqual(expected);
  expect(normalize(fs.readFileSync(path.join(DOCS, 'robots.txt'), 'utf8')))
    .toContain(`Sitemap: ${ORIGIN}/sitemap.xml`);
});

// Pages that must never reach an index. robots.txt is deliberately not used for
// them (§9 of CLAUDE.md): a disallowed URL can still be indexed URL-only.
test.each(['uninstall-ai-folders.html', 'uninstall-gemini-folders.html', 'stats/index.html'])(
  '%s is noindex', (rel) => {
    expect(fs.readFileSync(path.join(DOCS, rel), 'utf8')).toMatch(/<meta name="robots" content="noindex/);
  });
